{"command":"python - <<'PY'
import socket,struct,random
# Direct DNS questions against Docker resolver
for name in ['prices.internal','commons.local']:
 qid=random.randrange(65536); q=b''.join(bytes([len(x)])+x.encode() for x in name.split('.'))+b'\0'
 pkt=struct.pack('!HHHHHH',qid,0x100,1,0,0,0)+q+struct.pack('!HH',1,1)
 s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);s.settimeout(2)
 try:
  s.sendto(pkt,('127.0.0.11',53)); d,_=s.recvfrom(2048); print(name,d.hex())
 except Exception as e: print(name,e)
PY"}

